    bronze_millstonedresser = { name = "Bronast oblikovalec mlinskih kamnov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast oblikovalec mlinskih kamnov za mlinarje." },
