    gilded_millstonedresser = { name = "Pozlačen oblikovalec mlinskih kamnov", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen oblikovalec mlinskih kamnov za mlinarje." },
    jewel_set_millstonedresser = { name = "Draguljast oblikovalec mlinskih kamnov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast oblikovalec mlinskih kamnov za mlinarje." },
