    sovereign_millstonedresser_palace = { name = "Suverena millstonedresser palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillstoneDresserMaker.ironStock=16; MillstoneDresserMaker.bronzeStock=14; MillstoneDresserMaker.woodStock=12; MillstoneDresserMaker.leatherStock=8; MillstoneDresserMaker.silverStock=8; MillstoneDresserMaker.goldStock=6; MillstoneDresserMaker.jewelStock=4; MillstoneDresserMaker.pearlStock=4
MillstoneDresserMaker.productStock = {}; MillstoneDresserMaker.buildings = {}; MillstoneDresserMaker.maker = nil; MillstoneDresserMaker.activeMaking = {}; MillstoneDresserMaker.totalProducts = 0; MillstoneDresserMaker.dayTimer = 0
function MillstoneDresserMaker.init() MillstoneDresserMaker.ironStock=16; MillstoneDresserMaker.bronzeStock=14; MillstoneDresserMaker.woodStock=12; MillstoneDresserMaker.leatherStock=8; MillstoneDresserMaker.silverStock=8; MillstoneDresserMaker.goldStock=6; MillstoneDresserMaker.jewelStock=4; MillstoneDresserMaker.pearlStock=4; MillstoneDresserMaker.productStock={}; MillstoneDresserMaker.buildings={}; MillstoneDresserMaker.maker=nil; MillstoneDresserMaker.activeMaking={}; MillstoneDresserMaker.totalProducts=0; MillstoneDresserMaker.dayTimer=0; print("[MillstoneDresserMaker] Royal Millstone Dresser Maker System initialized (6 products, 4 buildings)") end
function MillstoneDresserMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneDresserMaker.maker={name=n or ("Oblikovalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblikovalec najet: %s (spretnost: %d)",MillstoneDresserMaker.maker.name,s),"success") end; return true end
function MillstoneDresserMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneDresserMaker.build(id) local ok,e=MillstoneDresserMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneDresserMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneDresserMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneDresserMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneDresserMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneDresserMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneDresserMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneDresserMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneDresserMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneDresserMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneDresserMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneDresserMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneDresserMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneDresserMaker.buildings==0 then return false,"Potrebna oblikovalna delavnica" end; if not MillstoneDresserMaker.maker then return false,"Potreben oblikovalec" end; return true end
function MillstoneDresserMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneDresserMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneDresserMaker.ironStock=MillstoneDresserMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneDresserMaker.bronzeStock=MillstoneDresserMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneDresserMaker.woodStock=MillstoneDresserMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneDresserMaker.leatherStock=MillstoneDresserMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneDresserMaker.silverStock=MillstoneDresserMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneDresserMaker.goldStock=MillstoneDresserMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneDresserMaker.jewelStock=MillstoneDresserMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneDresserMaker.pearlStock=MillstoneDresserMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneDresserMaker.maker then t=math.max(1,t-math.floor(MillstoneDresserMaker.maker.skill/13)) end; table.insert(MillstoneDresserMaker.activeMaking,{id="millstonedresser_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneDresserMaker.completeMaking(m) local q=1.0+(MillstoneDresserMaker.getQualityBonus()/100); if MillstoneDresserMaker.maker then q=q+(MillstoneDresserMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneDresserMaker.productStock[m.productType]=(MillstoneDresserMaker.productStock[m.productType] or 0)+m.quantity; MillstoneDresserMaker.totalProducts=MillstoneDresserMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneDresserMaker.maker then MillstoneDresserMaker.maker.itemsMade=MillstoneDresserMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneDresserMaker.maker.skill=math.min(100,MillstoneDresserMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblikovalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonedresser.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneDresserMaker.update(dt) if not _G.state then return end; MillstoneDresserMaker.dayTimer=MillstoneDresserMaker.dayTimer+dt; if MillstoneDresserMaker.dayTimer>=30 then MillstoneDresserMaker.dayTimer=0; for i=#MillstoneDresserMaker.activeMaking,1,-1 do local m=MillstoneDresserMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneDresserMaker.completeMaking(m); table.remove(MillstoneDresserMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneDresserMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneDresserMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneDresserMaker.getStats() return {ironStock=MillstoneDresserMaker.ironStock,bronzeStock=MillstoneDresserMaker.bronzeStock,woodStock=MillstoneDresserMaker.woodStock,leatherStock=MillstoneDresserMaker.leatherStock,silverStock=MillstoneDresserMaker.silverStock,goldStock=MillstoneDresserMaker.goldStock,jewelStock=MillstoneDresserMaker.jewelStock,pearlStock=MillstoneDresserMaker.pearlStock,productStock=MillstoneDresserMaker.productStock,numBuildings=#MillstoneDresserMaker.buildings,hasMaker=MillstoneDresserMaker.maker~=nil,makerName=MillstoneDresserMaker.maker and MillstoneDresserMaker.maker.name or "—",makerSkill=MillstoneDresserMaker.maker and MillstoneDresserMaker.maker.skill or 0,activeMaking=#MillstoneDresserMaker.activeMaking,totalProducts=MillstoneDresserMaker.totalProducts} end
return MillstoneDresserMaker
